 * A hand-written scanner for the token language described in the task: it
 * turns UTF-8 source text into a flat list of tokens, tracking 1-based line
 * and column positions (with 4-column tab stops) as it goes, or throws a
 * ScanError naming the first place the input does not scan.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

export class ScanError extends Error {
  constructor(line, col, message) {
    super(message)
    this.line = line
    this.col = col
  }
}

class Scanner {
  constructor(source) {
    this.s = source
    this.i = 0
    this.line = 1
    this.col = 1
  }

  atEnd() {
    return this.i >= this.s.length
  }

  // Looks at the UTF-16 code unit `offset` positions ahead without consuming
  // it. Every character this is compared against (punctuation, digits,
  // quotes, comment markers) is ASCII, so code-unit indexing is safe here.
  peekChar(offset = 0) {
    const idx = this.i + offset
    if (idx >= this.s.length) return null
    return this.s[idx]
  }

  // Consumes and returns the next full code point (as a one- or two-unit
  // string), updating line/column per the task's tab-stop and newline rules.
  advance() {
    const cp = this.s.codePointAt(this.i)
    const len = cp > 0xffff ? 2 : 1
    const ch = this.s.slice(this.i, this.i + len)
    this.i += len
    if (cp === 0x0a) {
      this.line += 1
      this.col = 1
    } else if (cp === 0x09) {
      this.col = (Math.floor((this.col - 1) / 4) + 1) * 4 + 1
    } else {
      this.col += 1
    }
    return ch
  }
}

const isDecimalDigit = (c) => c !== null && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== null && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== null && c >= '0' && c <= '7'
const isIdentStart = (c) => c !== null && /[A-Za-z_]/.test(c)
const isIdentPart = (c) => c !== null && /[A-Za-z0-9_]/.test(c)
const isPrefixLetter = (c) => c !== null && /[xXbBoO]/.test(c)

function digitTestForPrefix(letter) {
  switch (letter.toLowerCase()) {
    case 'x':
      return isHexDigit
    case 'b':
      return isBinDigit
    default:
      return isOctDigit
  }
}

// Consumes a run of digits satisfying `isDigit`, allowing a single `_`
// between two digits of that same run, and returns how many digits (not
// counting underscores) were consumed.
function consumeDigitRun(scanner, isDigit) {
  let count = 0
  while (true) {
    const c = scanner.peekChar()
    if (isDigit(c)) {
      scanner.advance()
      count += 1
      continue
    }
    if (c === '_' && count > 0 && isDigit(scanner.peekChar(1))) {
      scanner.advance()
      continue
    }
    break
  }
  return count
}

function consumeTrailingInvalid(scanner) {
  while (isIdentPart(scanner.peekChar())) scanner.advance()
}

function skipWhitespaceAndComments(scanner) {
  while (true) {
    const c = scanner.peekChar()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      scanner.advance()
      continue
    }
    if (c === '/' && scanner.peekChar(1) === '/') {
      scanner.advance()
      scanner.advance()
      while (scanner.peekChar() !== null && scanner.peekChar() !== '\n') scanner.advance()
      continue
    }
    if (c === '/' && scanner.peekChar(1) === '*') {
      const line = scanner.line
      const col = scanner.col
      scanner.advance()
      scanner.advance()
      let depth = 1
      while (depth > 0) {
        const cc = scanner.peekChar()
        if (cc === null) throw new ScanError(line, col, 'unterminated block comment')
        if (cc === '/' && scanner.peekChar(1) === '*') {
          scanner.advance()
          scanner.advance()
          depth += 1
          continue
        }
        if (cc === '*' && scanner.peekChar(1) === '/') {
          scanner.advance()
          scanner.advance()
          depth -= 1
          continue
        }
        scanner.advance()
      }
      continue
    }
    break
