      if (isDecimalDigit(scanner.peekChar(signOffset))) {
        scanner.advance() // 'e'/'E'
        if (hasSign) scanner.advance() // sign
        consumeDigitRun(scanner, isDecimalDigit)
      }
    }
  }
  if (isIdentPart(scanner.peekChar())) {
    consumeTrailingInvalid(scanner)
    throw new ScanError(line, col, `invalid number ${scanner.s.slice(startIndex, scanner.i)}`)
  }
  return { kind: 'number', line, col, text: scanner.s.slice(startIndex, scanner.i) }
}

function scanString(scanner, line, col) {
  scanner.advance() // opening quote
  let decoded = ''
  while (true) {
    const c = scanner.peekChar()
    if (c === null) throw new ScanError(line, col, 'unterminated string')
    if (c === '"') {
      scanner.advance()
      break
    }
    if (c === '\n') throw new ScanError(scanner.line, scanner.col, 'newline in string')
    if (c === '\\') {
      const escLine = scanner.line
      const escCol = scanner.col
      scanner.advance() // backslash
      const e = scanner.peekChar()
      if (e === null) throw new ScanError(line, col, 'unterminated string')
      if (e === 'n') {
        decoded += '\n'
        scanner.advance()
      } else if (e === 't') {
        decoded += '\t'
        scanner.advance()
      } else if (e === 'r') {
        decoded += '\r'
        scanner.advance()
      } else if (e === '\\') {
        decoded += '\\'
        scanner.advance()
      } else if (e === '"') {
        decoded += '"'
        scanner.advance()
      } else if (e === '0') {
        decoded += '\0'
        scanner.advance()
      } else if (e === 'x') {
        scanner.advance() // 'x'
        const h1 = scanner.peekChar()
        if (h1 === null) throw new ScanError(line, col, 'unterminated string')
        if (!isHexDigit(h1)) throw new ScanError(escLine, escCol, 'invalid escape \\x')
        scanner.advance()
        const h2 = scanner.peekChar()
        if (h2 === null) throw new ScanError(line, col, 'unterminated string')
        if (!isHexDigit(h2)) throw new ScanError(escLine, escCol, 'invalid escape \\x')
        scanner.advance()
        decoded += String.fromCharCode(parseInt(h1 + h2, 16))
      } else if (e === 'u') {
        scanner.advance() // 'u'
        const brace = scanner.peekChar()
        if (brace === null) throw new ScanError(line, col, 'unterminated string')
        if (brace !== '{') throw new ScanError(escLine, escCol, 'invalid escape \\u')
        scanner.advance() // '{'
        let hex = ''
        while (true) {
          const hc = scanner.peekChar()
          if (hc === null) throw new ScanError(line, col, 'unterminated string')
          if (hc === '}') break
          if (!isHexDigit(hc)) throw new ScanError(escLine, escCol, 'invalid escape \\u')
          hex += hc
          scanner.advance()
        }
        scanner.advance() // '}'
        const value = parseInt(hex, 16)
        if (hex.length === 0 || value > 0x10ffff) throw new ScanError(escLine, escCol, 'invalid escape \\u')
        decoded += String.fromCodePoint(value)
      } else {
