  if (isDecimalDigit(c)) return scanNumber(scanner, line, col)
  if (c === '"') return scanString(scanner, line, col)
  if (c === 'r' && scanner.peekChar(1) === '"') return scanRawString(scanner, line, col)
  const punct = scanPunct(scanner)
  if (punct !== null) return { kind: 'punct', line, col, text: punct }
  const ch = scanner.advance()
  throw new ScanError(line, col, `unexpected character ${ch}`)
}

