/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    usageError()
    return
  }

  const source = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scan(source)
  } catch (err) {
    if (!(err instanceof ScanError)) throw err
    process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
    process.exit(2)
    return
  }

  if (mode === 'tokens') {
    let out = ''
    for (const token of tokens) out += `${token.line}:${token.col} ${token.kind} ${token.text}\n`
    process.stdout.write(out)
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((kind) => [kind, 0]))
    for (const token of tokens) counts[token.kind] += 1
    let out = ''
    let total = 0
    for (const kind of STAT_KINDS) {
      out += `${kind} ${counts[kind]}\n`
      total += counts[kind]
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  }
  process.exit(0)
}

main()
"}

